//      CHECK( ParticleID( "Ra230[all]" ) == id.resolve( n, u238 ) );
//
//      // large internal id number - long on Windows is narrow
//      id = ReactionType( 109 );
//      CHECK( 3000000999 == id.number() );
//      CHECK( 109 == id.mt() );
//      CHECK( nuclear == id.interactionType() );
//      CHECK( "3a(t)" == id.symbol() );
//      CHECK( std::map< ParticleID, short >{ { a, 3 } }  == id.particles() );
//      CHECK( LevelID::all == id.level() );
//      CHECK( false == id.isSpecial() );
//      CHECK( true == id.isCompatibleWithENDF() );
//      CHECK( id == ReactionType( "3a(t)" ) );
//      CHECK( ParticleID( 86227, LevelID::all ) == id.resolve( n, u238 ) );
//
//      // large internal id number - long on Windows is narrow
//      id = ReactionType( 23 );
//      CHECK( 3000010999 == id.number() );
//      CHECK( 23 == id.mt() );
//      CHECK( nuclear == id.interactionType() );
//      CHECK( "n3a(t)" == id.symbol() );
//      CHECK( std::map< ParticleID, short >{ { n, 1 }, { a, 3 } }  == id.particles() );
//      CHECK( LevelID::all == id.level() );
//      CHECK( false == id.isSpecial() );
//      CHECK( true == id.isCompatibleWithENDF() );
//      CHECK( id == ReactionType( "n3a(t)" ) );
//      CHECK( id == ReactionType( "n3a" ) );
//      CHECK( id == ReactionType( "n,3a" ) );
//      CHECK( ParticleID( 86226, LevelID::all ) == id.resolve( n, u238 ) );

      // photoatomic and electroatomic reaction types
      id = ReactionType::total( InteractionType::Atomic );
      CHECK( 10000000501 == id.number() );
      CHECK( 501 == id.mt() );
      CHECK( atomic == id.interactionType() );
      CHECK( "total[atomic]" == id.symbol() );
      CHECK( std::nullopt == id.particles() );
      CHECK( std::nullopt == id.level() );
      CHECK( std::nullopt == id.partialDesignator() );
      CHECK( false == id.hasPartialDesignator() );
      CHECK( true == id.isSpecial() );
      CHECK( true == id.isCompatibleWithENDF() );
      CHECK( id == ReactionType( 501 ) );
      CHECK( id == ReactionType( "total[atomic]" ) );
      CHECK_THROWS( id.resolve( g, u ) );

      id = ReactionType( 502 );
      CHECK( 502 == id.number() );
      CHECK( 502 == id.mt() );
      CHECK( atomic == id.interactionType() );
      CHECK( "coherent" == id.symbol() );
      CHECK( empty == id.particles() );
      CHECK( std::nullopt == id.level() );
      CHECK( "coherent" == id.partialDesignator() );
      CHECK( true == id.hasPartialDesignator() );
      CHECK( false == id.isSpecial() );
      CHECK( true == id.isCompatibleWithENDF() );
      CHECK( id == ReactionType( "coherent" ) );
      CHECK( u == id.resolve( g, u ) );

      id = ReactionType( 504 );
      CHECK( 504 == id.number() );
